        let (_dir, root) = tree(&[("a.ts", format!("{long}\n{normal}\n").as_bytes())]);
        let result = search_files(&root, &["alpha"], &TextSearchOptions::default()).unwrap();
        assert_eq!(result.hits, hits(&root, &[("a.ts", vec![hit(1, &long[..4096]), hit(2, &normal)])]));
